use bhoo::android_calendar::{CalendarDate as D,CalendarState,days_in_month};
fn d(y:i32,m:u8,day:u8)->D {D::new(y,m,day).unwrap()}
#[test] fn weekdays_and_leap_years(){assert_eq!(d(1970,1,1).weekday(),5);assert_eq!(d(2024,2,29).weekday(),5);assert_eq!(d(2026,11,1).weekday(),1);assert_eq!(days_in_month(2000,2),29);assert_eq!(days_in_month(1900,2),28);assert!(D::new(2023,2,29).is_none());}
#[test] fn month_navigation_keeps_selection_and_respects_boundaries(){let mut s=CalendarState::new(d(2024,2,15),d(2024,4,10),d(2024,3,31),1).unwrap();assert!(s.move_month(-1));assert_eq!(s.selected(),d(2024,3,31));assert!(!s.move_month(-1));let c=s.cells();assert_eq!(c[4].unwrap().date,d(2024,2,1));assert!(!c[4].unwrap().enabled);assert!(c[18].unwrap().enabled);assert!(!s.select_day(14));assert!(s.select_day(15));assert_eq!(s.selected(),d(2024,2,15));assert!(s.move_month(1));assert!(s.move_month(1));assert!(!s.move_month(1));assert!(!s.select_day(11));}
#[test] fn selection_clamping_week_start_and_transactional_range(){let mut s=CalendarState::new(d(2025,1,5),d(2025,12,20),d(2024,3,1),2).unwrap();assert_eq!(s.selected(),d(2025,1,5));assert_eq!(s.cells()[2].unwrap().date,d(2025,1,1));assert!(s.set_date(d(2026,2,1)));assert_eq!(s.selected(),d(2025,12,20));assert!(s.set_range(d(2025,10,10),d(2025,9,9)).is_err());assert_eq!(s.range(),(d(2025,1,5),d(2025,12,20)));assert!(s.set_range(d(2025,1,1),d(2025,3,1)).is_ok());assert_eq!(s.selected(),d(2025,3,1));assert!(s.set_first_day_of_week(0).is_err());}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_calendar_view.rs"));}
#[test] fn xml_calendar_clicks_and_disabled_dates(){use bhoo::*;let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();state.wall_clock=Some(android_xml::WallClock{unix_seconds:1762732800.,offset_seconds:0,is_24_hour:true});let bounds=Rect{x:0.,y:0.,width:350.,height:356.};let render=|ui:&mut Ui,state:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,bounds,0.,|f|action=fixture::LAYOUT.render(f,bounds,state));action};render(&mut ui,&mut state,Input::default());assert_eq!(state.calendars["calendar"].visible_month(),(2025,11));let day=ui.semantics().iter().find(|n|n.label.as_ref()=="10").unwrap().bounds;let point=[day.x+day.width/2.,day.y+day.height/2.];render(&mut ui,&mut state,Input{pointer:Some(point),pressed:true,time:1.,..Input::default()});assert_eq!(render(&mut ui,&mut state,Input{pointer:Some(point),released:true,time:1.1,..Input::default()}),Some("calendar"));assert_eq!(state.calendars["calendar"].selected(),d(2025,11,10));let next=ui.semantics().iter().find(|n|n.label.as_ref()=="Next month").unwrap().bounds;let pt=[next.x+next.width/2.,next.y+next.height/2.];render(&mut ui,&mut state,Input{pointer:Some(pt),pressed:true,time:1.2,..Input::default()});render(&mut ui,&mut state,Input{pointer:Some(pt),released:true,time:1.3,..Input::default()});assert_eq!(state.calendars["calendar"].visible_month(),(2025,12));assert_eq!(state.calendars["calendar"].selected(),d(2025,11,10));}
#[test] fn touch_paging_does_not_select_and_cancel_or_vertical_drag_do_not_page(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.wall_clock=Some(android_xml::WallClock{unix_seconds:1762732800.,offset_seconds:0,is_24_hour:true});let bounds=Rect{x:0.,y:0.,width:350.,height:356.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut action=None;ui.frame(input,bounds,0.,|f|action=fixture::LAYOUT.render(f,bounds,s));action};draw(&mut ui,&mut s,Input::default());let start=s.calendars["calendar"].selected();let touch=|x,y,pressed,released,cancelled,time|Input{pointer:Some([x,y]),pointer_kind:PointerKind::Touch,pressed,released,cancelled,time,..Input::default()};draw(&mut ui,&mut s,touch(270.,150.,true,false,false,1.));draw(&mut ui,&mut s,touch(90.,150.,false,false,false,1.1));assert_eq!(draw(&mut ui,&mut s,touch(90.,150.,false,true,false,1.2)),None);assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));assert_eq!(s.calendars["calendar"].selected(),start);draw(&mut ui,&mut s,touch(250.,150.,true,false,false,2.));draw(&mut ui,&mut s,touch(60.,150.,false,false,false,2.1));draw(&mut ui,&mut s,touch(60.,150.,false,false,true,2.2));assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));draw(&mut ui,&mut s,touch(200.,100.,true,false,false,3.));draw(&mut ui,&mut s,touch(180.,250.,false,false,false,3.1));draw(&mut ui,&mut s,touch(180.,250.,false,true,false,3.2));assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));}
#[test] fn short_fast_fling_advances_but_slow_short_drag_returns(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.wall_clock=Some(android_xml::WallClock{unix_seconds:1762732800.,offset_seconds:0,is_24_hour:true});let b=Rect{x:0.,y:0.,width:350.,height:356.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let touch=|x,pressed,released,time|Input{pointer:Some([x,150.]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()};draw(&mut ui,&mut s,Input::default());draw(&mut ui,&mut s,touch(250.,true,false,1.));draw(&mut ui,&mut s,touch(215.,false,false,1.05));draw(&mut ui,&mut s,touch(215.,false,true,1.06));assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));draw(&mut ui,&mut s,touch(250.,true,false,2.));draw(&mut ui,&mut s,touch(210.,false,false,2.5));draw(&mut ui,&mut s,touch(210.,false,true,2.6));assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));}
#[test] fn locale_snapshot_and_week_start_control_rendered_grid(){use bhoo::*;use bhoo::android_calendar::CalendarLocale;let mut fields=vec!["2".to_owned(),"ltr".to_owned(),"{year} / {month}".to_owned(),"{weekday} {day} {month}".to_owned(),"DMY".to_owned(),"last".to_owned(),"h12".to_owned(),"h23".to_owned(),"0".to_owned(),"0".to_owned(),":".to_owned()];fields.extend((1..=12).map(|i|format!("month{i}")));fields.extend((0..7).map(|i|format!("day{i}")));fields.extend((0..10).map(|i|format!("[{i}]")));fields.extend((1..=12).map(|i|format!("m{i}")));fields.extend((0..7).map(|i|format!("w{i}")));fields.extend(["AM".into(),"PM".into()]);let data=fields.join("\n");let locale=CalendarLocale::from_host(&data).unwrap();assert_eq!(locale.title(2025,11),"[2][0][2][5] / month11");assert_eq!(locale.number(15),"[1][5]");assert_eq!(locale.date_label(d(2025,11,1)),"w6 [1] m11");assert!(CalendarLocale::from_host("2\n{year}").is_none());let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();state.calendar_locale=locale;state.wall_clock=Some(android_xml::WallClock{unix_seconds:1762732800.,offset_seconds:0,is_24_hour:true});let bounds=Rect{x:0.,y:0.,width:350.,height:356.};ui.frame(Input::default(),bounds,0.,|f|{fixture::LAYOUT.render(f,bounds,&mut state);});assert_eq!(state.calendars["calendar"].first_day_of_week(),2);let first=ui.semantics().iter().find(|n|n.label.as_ref()=="[1]").unwrap();assert!((first.bounds.x-(20.0+5.0*310.0/7.0)).abs()<0.01);}
#[test] fn hides_unavailable_month_arrows_at_range_limits(){use bhoo::*;let mut ui=Ui::default();let mut state=android_xml::LayoutState::default();state.calendars.insert("calendar".into(),CalendarState::new(d(2024,5,10),d(2024,6,12),d(2024,5,10),1).unwrap());let b=Rect{x:0.,y:0.,width:350.,height:356.};ui.frame(Input::default(),b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});assert!(!ui.semantics().iter().any(|n|n.label.as_ref()=="Previous month"));assert!(ui.semantics().iter().any(|n|n.label.as_ref()=="Next month"));assert!(!ui.semantics().iter().find(|n|n.label.as_ref()=="9").unwrap().enabled);}
#[test] fn rtl_mirrors_days_and_swipe_direction(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.rtl=true;s.wall_clock=Some(android_xml::WallClock{unix_seconds:1762732800.,offset_seconds:0,is_24_hour:true});let b=Rect{x:0.,y:0.,width:350.,height:356.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});draw(&mut ui,&mut s,Input::default());let previous=ui.semantics().iter().find(|n|n.label.as_ref()=="Previous month").unwrap().bounds;let next=ui.semantics().iter().find(|n|n.label.as_ref()=="Next month").unwrap().bounds;assert!(previous.x>next.x);let first=ui.semantics().iter().find(|n|n.label.as_ref()=="1").unwrap().bounds;assert!((first.x-20.0).abs()<0.01);let touch=|x,pressed,released,time|Input{pointer:Some([x,150.]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()};draw(&mut ui,&mut s,touch(70.,true,false,1.));draw(&mut ui,&mut s,touch(260.,false,false,1.1));draw(&mut ui,&mut s,touch(260.,false,true,1.2));assert_eq!(s.calendars["calendar"].visible_month(),(2025,12));}
